import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        rows = [row for row in packages[name]
                if row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + rows)

    best_vector = None
    best_versions = None
    ordered_names = names if name_order == "ascending" else list(reversed(names))
    for selection in product(*choices):
        assigned = {name: row for name, row in zip(names, selection)
                    if row is not None}
        if any(name not in assigned or not bounds[0] <= assigned[name]["version"] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue

        edges = {}
        valid = True
        for name, row in assigned.items():
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if (other not in assigned or
                        not dep["min"] <= assigned[other]["version"] <= dep["max"]):
                    valid = False
                    break
                deps.append(other)
            edges[name] = deps
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(assigned):
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in assigned):
            continue

        vector = tuple(assigned[name]["version"] if name in assigned else -1
                       for name in ordered_names)
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best_vector = vector
            best_versions = {name: row["version"] for name, row in assigned.items()}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def rounded(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def ledger(data):
    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = [job["id"] for job in subset]
        id_set = set(ids)
        if not mandatory <= id_set:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        feasible = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best is None or value > best_value or
                (value == best_value and selected < best)):
            best, best_value = selected, value
    if best is None:
        return {"error": "impossible"}
    return {"selected": best, "value": best_value}


def routes(data):
    required = data.get("required", [])
    index = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = (1 << index[start]) if start in index else 0
    initial = (start, initial_mask, data["coupons"])
    best = {initial: data["start"]}
    queue = [(data["start"], start, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if time != best.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask
                if next_node in index:
                    next_mask |= 1 << index[next_node]
                next_state = (next_node, next_mask, next_remaining)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
    return {"arrival": None}


